const BASE_URL = 'https://api.test';
const PATH = '/ws/feed';
const MESSAGE = 'Watch';
const KEY_MEMBER = 'threadId';

/** One socket the platform opened: what the app sent and closed is the test's log. */
class FakeSocket implements LiveSocket {
  closedByApp = false;

  constructor(
    readonly events: SocketEvents,
    private readonly log: string[],
  ) {}

  send(text: string): void {
    this.log.push(`send ${text}`);
  }

  close(): void {
    this.closedByApp = true;
    this.log.push('close');
  }
}

/** A platform whose clock and sockets a test drives by hand; the jitter is always its low end. */
class ManualPlatform {
  readonly log: string[] = [];
  private now = 0;
  private started = 0;
  private readonly waiting = new Set<{ at: number; order: number; run: () => void }>();
  private current: FakeSocket | null = null;

  randomFraction(): number {
    return 0;
  }

  after(milliseconds: number, callback: () => void): Cancel {
    const entry = { at: this.now + milliseconds, order: this.started++, run: callback };
    this.waiting.add(entry);
    return () => {
      this.waiting.delete(entry);
    };
  }

  openSocket(address: string, subprotocols: readonly string[], events: SocketEvents): LiveSocket {
    this.log.push(`open ${address} ${subprotocols.join(',')}`);
    this.current = new FakeSocket(events, this.log);
    return this.current;
  }

  /** The server accepts the newest connection. */
  accept(): void {
    this.current?.events.opened();
  }

  /** The server sends *text* on the newest connection; a connection the app closed hears nothing. */
  receive(text: string): void {
    if (this.current !== null && !this.current.closedByApp) {
      this.current.events.frame(text);
    }
  }

  /** The newest connection closes with *code*, unless the app closed it first. */
  closeFromServer(code: number): void {
    if (this.current !== null && !this.current.closedByApp) {
      this.current.events.closed(code);
    }
  }

  advance(milliseconds: number): void {
    const until = this.now + milliseconds;
    for (;;) {
      const due = [...this.waiting]
        .filter((entry) => entry.at <= until)
        .sort((a, b) => a.at - b.at || a.order - b.order);
      const entry = due[0];
      if (entry === undefined) {
        break;
      }
      this.waiting.delete(entry);
      this.now = entry.at;
      entry.run();
    }
    this.now = until;
  }
}

/** A session whose token a test sets; `null` is signed out. */
class FakeSession {
  private readonly token = signal<string | null>(null);

  get accessToken(): string | null {
    return this.token();
  }

  set(token: string | null): void {
    this.token.set(token);
  }
}

interface Owner {
  readonly injector: EnvironmentInjector;
  readonly key: ReturnType<typeof signal<string>>;
}

function configure(apiBaseUrl: string | null): { platform: ManualPlatform; session: FakeSession } {
  const platform = new ManualPlatform();
  const session = new FakeSession();
  TestBed.configureTestingModule({
    providers: [
      { provide: BrowserPlatform, useValue: platform },
      { provide: SessionService, useValue: session },
      { provide: RUNTIME_CONFIG, useValue: { apiBaseUrl } },
    ],
  });
  return { platform, session };
}

describe('an owner\'s live subscriptions', () => {
  beforeEach(() => {
    TestBed.resetTestingModule();
  });

  afterEach(() => {
    TestBed.resetTestingModule();
  });

  for (const { title, ops, log } of LIVE_CASES) {
    it(title, () => {
      const { platform, session } = configure(BASE_URL);
      const owners = new Map<string, Owner>();
      const hold = (name: string, key: string): void => {
        const injector = createEnvironmentInjector([], TestBed.inject(EnvironmentInjector));
        const keySignal = signal(key);
        owners.set(name, { injector, key: keySignal });
        const scope = runInInjectionContext(injector, () => new LiveScope());
        scope.hold({
          path: PATH,
          message: MESSAGE,
          keyMember: KEY_MEMBER,
          subscription: () => (keySignal() === '' ? null : { [KEY_MEMBER]: keySignal() }),
          events: { Changed: (payload) => platform.log.push(`${name}.Changed ${JSON.stringify(payload)}`) },
          onReconnect: () => platform.log.push(`${name}.onReconnect`),
          onRefused: () => platform.log.push(`${name}.onRefused`),
          onClosed: () => platform.log.push(`${name}.onClosed`),
        });
      };
      for (const op of ops) {
        switch (op.kind) {
          case 'signIn':
            session.set(op.text);
            break;
          case 'signOut':
            session.set(null);
            break;
          case 'hold':
            hold(op.owner, op.key);
            break;
          case 'rekey':
            owners.get(op.owner)?.key.set(op.key);
            break;
          case 'destroy':
            owners.get(op.owner)?.injector.destroy();
            break;
          case 'accept':
            platform.accept();
            break;
          case 'receive':
            platform.receive(op.text);
            break;
          case 'close':
            platform.closeFromServer(op.code);
            break;
          case 'advance':
            platform.advance(op.ms);
            break;
          default:
            throw new Error(`No live step '${op.kind}'.`);
        }
        TestBed.tick();
      }
      expect(platform.log).toEqual(log);
    });
  }

  it('derives the WebSocket address from the API address and the published path', () => {
    expect(socketAddress('https://api.test', '/ws/feed')).toBe('wss://api.test/ws/feed');
    expect(socketAddress('http://localhost:8080', '/ws/feed')).toBe('ws://localhost:8080/ws/feed');
  });

  it('refuses an app with no API address, or one that is not http or https', () => {
    expect(() => socketAddress(null, '/ws/feed')).toThrow(/API address/);
    expect(() => socketAddress('', '/ws/feed')).toThrow(/API address/);
    expect(() => socketAddress('ftp://api.test', '/ws/feed')).toThrow(/http or https/);
  });

  it('never carries the session token in the address', () => {
    const { platform, session } = configure(BASE_URL);
    session.set('secret-token');
    const injector = createEnvironmentInjector([], TestBed.inject(EnvironmentInjector));
    const scope = runInInjectionContext(injector, () => new LiveScope());
    scope.hold({
      path: PATH,
      message: MESSAGE,
      keyMember: KEY_MEMBER,
      subscription: () => ({ [KEY_MEMBER]: 'k1' }),
      events: {},
    });
    TestBed.tick();
    const [opened] = platform.log;
    expect(opened).toBeDefined();
    const [, address] = (opened ?? '').split(' ');
    expect(address).not.toContain('secret-token');
    expect(address).not.toContain('?');
  });
});
